#include <iostream>
#include <iomanip>
using namespace std;

double average(int a, int b, int c) { return (a + b + c) / 3.0; }
char letter(double avg)
{
    if (avg >= 90) return 'A';
    if (avg >= 80) return 'B';
    if (avg >= 70) return 'C';
    if (avg >= 60) return 'D';
    return 'F';
}
bool passed(char grade) { return grade != 'F'; }
int main()
{
    int a, b, c;
    cin >> a >> b >> c;
    double avg = average(a, b, c);
    char g = letter(avg);
    cout << fixed << setprecision(1);
    cout << "Average: " << avg << endl;
    cout << "Grade: " << g << endl;
    cout << (passed(g) ? "Passed" : "Failed") << endl;
    return 0;
}

#include <iostream>
using namespace std;

void orderPair(int& x, int& y)
{
    if (x > y)
    {
        int t = x;
        x = y;
        y = t;
    }
}
int main()
{
    int a, b, c;
    cin >> a >> b >> c;
    orderPair(a, b);
    orderPair(b, c);
    orderPair(a, b);
    cout << a << " " << b << " " << c << endl;
    return 0;
}

