#include <iostream>
#include <iomanip>
using namespace std;

double area(double radius) { return 3.14159 * radius * radius; }
double area(double length, double width) { return length * width; }
double area(double length, double width, double height)
{
    return 2 * (length * width + length * height + width * height);
}
int main()
{
    double l, w, h;
    cin >> l >> w >> h;
    cout << fixed << setprecision(2);
    cout << "Circle: " << area(l) << endl;
    cout << "Rectangle: " << area(l, w) << endl;
    cout << "Box: " << area(l, w, h) << endl;
    return 0;
}

#include <iostream>
using namespace std;

void makeChange(int cents, int& quarters, int& dimes, int& nickels, int& pennies)
{
    quarters = cents / 25;
    cents = cents % 25;
    dimes = cents / 10;
    cents = cents % 10;
    nickels = cents / 5;
    pennies = cents % 5;
}
int main()
{
    int cents, q, d, n, p;
    cin >> cents;
    makeChange(cents, q, d, n, p);
    cout << "Quarters: " << q << endl;
    cout << "Dimes: " << d << endl;
    cout << "Nickels: " << n << endl;
    cout << "Pennies: " << p << endl;
    return 0;
}
